package com.benkeyshop;
import java.sql.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
/** DAO transaksi dan laporan. */
public class SalesDAO {
 public void save(Sale sale,Map<Long,CartItem> cart)throws SQLException{try(Connection c=DB.connect()){c.setAutoCommit(false);try{
  for(CartItem i:cart.values())try(PreparedStatement p=c.prepareStatement("SELECT stock FROM products WHERE id=? FOR UPDATE")){p.setLong(1,i.getProduct().getId());try(ResultSet r=p.executeQuery()){if(!r.next()||r.getInt(1)<i.getQuantity())throw new SQLException("Stok tidak cukup: "+i.getProduct().getName());}}
  long saleId;try(PreparedStatement p=c.prepareStatement("INSERT INTO sales(receipt_no,buyer_name,subtotal,discount,total,paid,change_amount) VALUES(?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,sale.getReceiptNo());p.setString(2,sale.getBuyerName());p.setBigDecimal(3,sale.getSubtotal());p.setBigDecimal(4,sale.getDiscount());p.setBigDecimal(5,sale.getTotal());p.setBigDecimal(6,sale.getPaid());p.setBigDecimal(7,sale.getChangeAmount());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();saleId=k.getLong(1);}}
  for(CartItem i:cart.values()){Product p=i.getProduct();try(PreparedStatement q=c.prepareStatement("INSERT INTO sale_items(sale_id,product_id,sku_snapshot,product_name_snapshot,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?,?)")){q.setLong(1,saleId);q.setLong(2,p.getId());q.setString(3,p.getSku());q.setString(4,p.getName());q.setBigDecimal(5,p.getPrice());q.setInt(6,i.getQuantity());q.setBigDecimal(7,i.getSubtotal());q.executeUpdate();}try(PreparedStatement q=c.prepareStatement("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?")){q.setInt(1,i.getQuantity());q.setLong(2,p.getId());q.setInt(3,i.getQuantity());if(q.executeUpdate()!=1)throw new SQLException("Stok berubah.");}}
  c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public List<Object[]> report(LocalDate a,LocalDate b)throws SQLException{List<Object[]> out=new ArrayList<>();try(Connection c=DB.connect();PreparedStatement p=c.prepareStatement("SELECT receipt_no,sold_at,buyer_name,subtotal,discount,total FROM sales WHERE sold_at>=? AND sold_at<? ORDER BY sold_at DESC")){p.setString(1,a+" 00:00:00");p.setString(2,b.plusDays(1)+" 00:00:00");try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Object[]{r.getString(1),r.getTimestamp(2),r.getString(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6)});}}return out;}
 public BigDecimal[] summary(LocalDate a,LocalDate b)throws SQLException{try(Connection c=DB.connect();PreparedStatement p=c.prepareStatement("SELECT COUNT(*),COALESCE(SUM(total),0),COALESCE(AVG(total),0) FROM sales WHERE sold_at>=? AND sold_at<?")){p.setString(1,a+" 00:00:00");p.setString(2,b.plusDays(1)+" 00:00:00");try(ResultSet r=p.executeQuery()){r.next();return new BigDecimal[]{BigDecimal.valueOf(r.getLong(1)),r.getBigDecimal(2),r.getBigDecimal(3)};}}}
 public BigDecimal[] today()throws SQLException{try(Connection c=DB.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*),COALESCE(SUM(total),0) FROM sales WHERE DATE(sold_at)=CURDATE()")){r.next();return new BigDecimal[]{BigDecimal.valueOf(r.getLong(1)),r.getBigDecimal(2)};}}
}
